/* No remote API or account required; curated dataset and device-local saved items. */
(() => {
 'use strict';
 const D=window.ATLAS;
 if(!D){document.getElementById('view-content').textContent='자료를 불러오지 못했습니다. 페이지를 새로고침해 주세요.';return;}
 const $=id=>document.getElementById(id);
 const E=new Map(D.entities.map(e=>[e.id,e]));
 const S=new Map(D.sources.map(s=>[s.id,s]));
 const K={technology:'기술',organization:'기업·기관',product:'제품·장비',mission:'실증임무'};
 const colors={technology:'#76e4ce',organization:'#abc1d5',product:'#9cb8ff',mission:'#d2adf4'};
 const views={map:['관계 지도','◇','EXPLORE THE CONNECTIONS','기술에서 실증까지, 연결해서 보기','기술·제품·기관·임무를 선택하고 연결된 근거를 확인하세요.'],catalog:['기업·제품','▤','ORGANIZATIONS & PRODUCTS','누가 개발하고, 어디에 쓰일까요?','공식 자료에 연결된 기업·기관과 제품을 탐색합니다.'],missions:['실증임무','◎','MISSIONS & DEMONSTRATIONS','궤도에서 확인된 기술의 발자취','발사, 실증 성과, 자료상 운용 상태를 구분해서 살펴봅니다.'],timeline:['변화 타임라인','≋','MILESTONES & CHANGES','개발부터 실증까지, 변화의 기록','실제 사건 날짜와 자료 발표·갱신 날짜를 구분해 기록합니다.'],saved:['관심 목록','☆','YOUR RESEARCH COLLECTION','다시 살펴볼 기술과 기관','별표로 저장한 항목입니다. 현재 브라우저에만 보관됩니다.'],sources:['근거 자료','↗','SOURCES & METHODOLOGY','모든 연결은 근거에서 시작합니다','출처의 성격과 발표·검토 시점을 확인하세요.']};
 let saved=new Set();let storageAvailable=true;
 try{const raw=JSON.parse(localStorage.getItem('sat-tech-atlas.saved.v1')||'[]');if(Array.isArray(raw))saved=new Set(raw.filter(id=>typeof id==='string'&&E.has(id)));}catch{storageAvailable=false;}
 const state={view:'map',field:'all',type:'all',query:'',focus:D.fields[0].root,sourceCountry:'all',sourceType:'all'};
 let toastTimer,resizeTimer,returnFocus=null,graphPage=0,graphKey='';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safeUrl=url=>{try{const u=new URL(url);return u.protocol==='https:'?u.href:'#';}catch{return '#';}};
 const fieldOf=id=>D.fields.find(f=>f.id===id);
 const research=window.createAtlasResearch(D);
 const {neighbors,inField,normalize,matches,sourceIds}=research;
 const nodeLinks=id=>neighbors(id).map(n=>n.link);
 function filteredEntities(){return D.entities.filter(e=>inField(e,state.field)&&(state.type==='all'||e.type===state.type)&&matches(e,state.query));}
 function pageEntities(){let list=filteredEntities();if(state.view==='catalog'&&state.type==='all')list=list.filter(e=>['organization','product'].includes(e.type));if(state.view==='missions')list=list.filter(e=>e.type==='mission');if(state.view==='saved')list=list.filter(e=>saved.has(e.id));return list;}
 function evidenceClass(e){return /개발사/.test(e.status)?'vendor':/설계|기술조사|자료/.test(e.status)?'plan':'';}
 function pill(e){return '<span class="status-pill '+evidenceClass(e)+'">'+esc(e.status)+'</span>';}
 function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3300);}
 function saveItem(id){if(!E.has(id))return;const added=!saved.has(id);if(added)saved.add(id);else saved.delete(id);try{localStorage.setItem('sat-tech-atlas.saved.v1',JSON.stringify([...saved]));}catch{storageAvailable=false;}renderNavigation();if(state.view==='saved')renderContent();document.querySelectorAll('[data-save="'+id+'"]').forEach(b=>{b.classList.toggle('is-saved',added);b.setAttribute('aria-pressed',String(added));if(b.classList.contains('small-star')){b.textContent=added?'★':'☆';b.setAttribute('aria-label',E.get(id).name+(added?' 관심 목록에서 해제':' 관심 목록에 저장'));}else b.textContent=added?'★ 관심 목록에 저장됨':'☆ 관심 목록에 저장';});toast(storageAvailable?(added?'관심 목록에 저장했습니다.':'관심 목록에서 해제했습니다.'):'브라우저 저장을 사용할 수 없어 이번 화면에서만 유지됩니다.');}
 function readHash(){const raw=location.hash.slice(1).split('?');if(views[raw[0]])state.view=raw[0];const p=new URLSearchParams(raw[1]||'');if(p.has('field')&&(p.get('field')==='all'||fieldOf(p.get('field'))))state.field=p.get('field');if(E.has(p.get('focus')))state.focus=p.get('focus');}
 function writeHash(){const params=new URLSearchParams({field:state.field,focus:state.focus});history.replaceState(null,'','#'+state.view+'?'+params);}
 function renderNavigation(){
  $('navigation').innerHTML=Object.entries(views).map(([id,v])=>'<button type="button" class="nav-item '+(state.view===id?'active':'')+'" data-view="'+id+'" '+(state.view===id?'aria-current="page"':'')+'><span class="nav-symbol" aria-hidden="true">'+v[1]+'</span>'+v[0]+(id==='saved'?'<span class="nav-count">'+saved.size+'</span>':'')+'</button>').join('');
  $('fields').innerHTML=[{id:'all',name:'전체 분야'},...D.fields].map(f=>'<button type="button" class="field-item '+(state.field===f.id?'active':'')+'" aria-pressed="'+(state.field===f.id)+'" data-field="'+f.id+'"><span class="field-marker" aria-hidden="true"></span><span>'+esc(f.name)+'</span></button>').join('');
 }
 function renderSummary(){const list=D.entities.filter(e=>inField(e,state.field));const items=[[D.fields.length,'탐색 분야'],[list.filter(e=>e.type==='organization').length,'기업·기관'],[list.filter(e=>e.type==='product').length,'제품·장비'],[list.filter(e=>e.type==='mission').length,'실증임무']];$('summary').innerHTML=items.map(([n,l])=>'<div class="summary-item"><strong class="summary-number">'+n+'</strong><span class="summary-label">'+l+'</span></div>').join('');}
 function renderContext(){const n=pageEntities().length;$('active-context').innerHTML='<label class="context-label">분야 <select id="mobile-field" aria-label="탐색 분야" style="border:0;background:transparent;color:inherit;font:inherit;max-width:230px">'+[{id:'all',name:'전체 분야'},...D.fields].map(f=>'<option value="'+f.id+'" '+(state.field===f.id?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select></label><span>'+ (state.view==='sources'?'공공기관 자료와 개발사 자료를 구분합니다.':state.view==='timeline'?'연도·월까지만 확인된 기록은 원래 정밀도로 표시합니다.':n+'개 항목'+(state.query?' · “'+esc(state.query)+'” 검색':''))+'</span>';}
 function render(){renderNavigation();const v=views[state.view];$('current-view').textContent=v[0];$('page-eyebrow').textContent=v[2];$('page-title').textContent=v[3];$('page-description').textContent=v[4];$('type-filter').value=state.type;$('type-filter').disabled=state.view==='sources';$('search').placeholder=state.view==='sources'?'자료 제목, 기관, 국가, 확인 내용 검색':'기술, 기업, 제품, 위성 검색';$('export-button').textContent=state.view==='saved'?'관심 목록 내보내기 ↗':'현재 목록 내보내기 ↗';renderSummary();renderContext();renderContent();writeHash();}
 function empty(title,message){return '<div class="empty-state"><p class="overline">NO MATCHING RECORDS</p><h2>'+esc(title)+'</h2><p>'+esc(message)+'</p><button class="button secondary" type="button" data-reset>필터 초기화</button></div>';}
 function card(e){return '<article class="entity-card"><div class="card-top"><span class="kind-label">'+K[e.type]+'</span><button type="button" class="small-star '+(saved.has(e.id)?'is-saved':'')+'" data-save="'+e.id+'" aria-pressed="'+saved.has(e.id)+'" aria-label="'+esc(e.name)+(saved.has(e.id)?' 관심 목록에서 해제':' 관심 목록에 저장')+'">'+(saved.has(e.id)?'★':'☆')+'</button></div><button class="card-title-button" type="button" data-open="'+e.id+'"><h3>'+esc(e.name)+'</h3></button><span class="field-tag">'+esc(e.subtitle)+'</span><p>'+esc(e.summary)+'</p><div class="card-footer">'+pill(e)+'<button class="text-link" type="button" data-focus="'+e.id+'">관계 보기 ↗</button></div></article>';}
 function renderContent(){const container=$('view-content');renderContext();
  if(state.view==='map'){if(state.query||state.type!=='all'){const list=pageEntities();container.innerHTML=list.length?'<div class="results-heading"><h2>검색 결과에서 관계 탐색 시작</h2><span>'+list.length+'개</span></div><div class="result-grid">'+list.map(card).join('')+'</div>':empty('일치하는 항목이 없습니다.','다른 이름으로 검색하거나 분야·유형 필터를 초기화해 보세요.');return;}renderMap();return;}
  if(state.view==='timeline'){renderTimeline();return;}
  if(state.view==='sources'){renderSources();return;}
  const list=pageEntities();
  if(!list.length){container.innerHTML=empty(state.view==='saved'?'표시할 관심 항목이 없습니다.':'일치하는 항목이 없습니다.',state.view==='saved'?'관심 있는 항목의 별표를 누르거나 분야 필터를 확인해 주세요.':'검색어와 필터 조건을 확인해 주세요.');return;}
  if(state.view==='missions'){container.innerHTML='<div class="view-toolbar"><div><h2>대표 실증임무</h2><p>상태는 연결된 자료의 발표 시점 기준입니다.</p></div><span class="field-tag">'+list.length+'개 임무</span></div><div class="mission-table-wrap"><table class="mission-table"><thead><tr><th>임무</th><th>발사</th><th>확인된 기록</th><th>검토할 범위</th></tr></thead><tbody>'+list.sort((a,b)=>b.launch.localeCompare(a.launch)).map(e=>'<tr><td><button type="button" data-open="'+e.id+'">'+esc(e.name)+'</button><small>'+fieldOf(e.field).short+'</small></td><td>'+esc(e.launch)+'</td><td>'+pill(e)+'<small>'+esc(e.summary)+'</small></td><td>'+esc(e.notes)+'<small><button class="text-link" type="button" data-focus="'+e.id+'">관계 보기 ↗</button></small></td></tr>').join('')+'</tbody></table></div>';return;}
  container.innerHTML=(state.view==='catalog'?'<div class="view-toolbar"><div><h2>기업·기관과 제품</h2><p>국가·기업의 기술력 순위를 의미하지 않습니다.</p></div><span class="field-tag">'+list.length+'개</span></div>':'')+'<div class="result-grid">'+list.map(card).join('')+'</div>';
 }
 function renderMap(){let focus=E.get(state.focus);if(!focus||!inField(focus,state.field)){focus=E.get((fieldOf(state.field)||D.fields[0]).root);state.focus=focus.id;}
  const connections=neighbors(focus.id).filter(x=>inField(x.entity,state.field));
  const unique=[...new Map(connections.map(n=>[n.entity.id,n])).values()];
  const order={product:0,mission:1,technology:2,organization:3};
  unique.sort((a,b)=>order[a.entity.type]-order[b.entity.type]);
  const key=focus.id+':'+state.field;
  if(graphKey!==key){graphKey=key;graphPage=0;}
  const pageCount=Math.max(1,Math.ceil(unique.length/8));
  graphPage=Math.min(graphPage,pageCount-1);
  const shown=unique.slice(graphPage*8,(graphPage+1)*8);
  $('view-content').innerHTML='<div class="atlas-layout"><div class="graph-panel"><div class="graph-caption"><div><h2>'+esc(focus.name)+'의 연결</h2><p>항목은 탐색, 연결선은 근거 보기</p></div><button type="button" class="graph-home" data-root>분야 중심으로</button></div><div class="graph-stage" id="graph-stage"></div><div class="graph-legend">'+Object.entries(K).map(([id,name])=>'<span class="legend-item"><span class="legend-dot" style="background:'+colors[id]+'"></span>'+name+'</span>').join('')+'<span class="graph-overflow">직접 연결 '+unique.length+'개'+(unique.length>shown.length?' · 지도 '+shown.length+'개 표시':'')+'</span></div><div class="graph-nav-list" aria-label="분야 내 기술 바로가기">'+D.entities.filter(e=>e.type==='technology'&&(state.field==='all'||e.field===state.field)).map(e=>'<button type="button" data-focus="'+e.id+'">'+esc(e.name)+'</button>').join('')+'</div></div><aside class="detail-panel" aria-label="선택 항목 상세">'+detailHtml(focus,false)+'</aside></div>';
  if(pageCount>1){
   const controls=document.createElement('div');
   controls.className='graph-nav-list';
   controls.setAttribute('aria-label','연결 항목 페이지');
   controls.innerHTML='<button type="button" data-graph-page="'+(graphPage-1)+'" '+(graphPage===0?'disabled':'')+'>이전 연결</button><span role="status" style="color:#bcd2e1">'+(graphPage+1)+' / '+pageCount+' 페이지</span><button type="button" data-graph-page="'+(graphPage+1)+'" '+(graphPage===pageCount-1?'disabled':'')+'>다음 연결</button>';
   controls.addEventListener('click',event=>{const button=event.target.closest('[data-graph-page]');if(!button||button.disabled)return;const next=Number(button.dataset.graphPage);graphPage=next;renderMap();const selector=next===pageCount-1?'[data-graph-page="'+(next-1)+'"]':'[data-graph-page="'+(next+1)+'"]';document.querySelector(selector)?.focus();});
   $('graph-stage').after(controls);
  }
  drawGraph(focus,shown);
 }
 function nameLines(name){const lines=[];let line='',width=0;for(const char of name){const units=/[^\u0000-\u00ff]/.test(char)?2:1;if(width+units>18&&line){lines.push(line.trim());line='';width=0;}line+=char;width+=units;}if(line.trim())lines.push(line.trim());return lines.length>2?[lines[0],lines[1].slice(0,-1)+'…']:lines;}
 function drawGraph(focus,shown){const el=$('graph-stage');if(!el)return;const w=Math.max(620,Math.round(el.clientWidth));const h=510,cx=w/2,cy=h/2,rx=(w-190)/2,ry=190;
  const positions=new Map([[focus.id,{x:cx,y:cy}]]);shown.forEach((n,i)=>{const angle=-Math.PI/2+i*2*Math.PI/shown.length;positions.set(n.entity.id,{x:cx+Math.cos(angle)*rx,y:cy+Math.sin(angle)*ry});});
  const edgeHtml=shown.map(n=>{const p=positions.get(n.entity.id),x=(cx+p.x)/2,y=(cy+p.y)/2;return '<g role="button" tabindex="0" data-edge="'+n.link.id+'" aria-label="'+esc(focus.name+' · '+n.link.label+' · '+n.entity.name)+' 관계 근거"><line class="graph-edge" x1="'+cx+'" y1="'+cy+'" x2="'+p.x+'" y2="'+p.y+'"/><line stroke="transparent" stroke-width="22" x1="'+cx+'" y1="'+cy+'" x2="'+p.x+'" y2="'+p.y+'"/><text class="edge-label" text-anchor="middle" x="'+x+'" y="'+(y-6)+'">'+esc(n.link.label)+'</text></g>';}).join('');
  const nodeHtml=[focus,...shown.map(n=>n.entity)].map(e=>{const p=positions.get(e.id);const lines=nameLines(e.name);const central=e.id===focus.id;return '<g class="graph-node '+(central?'central':'')+'" role="button" tabindex="0" data-focus="'+e.id+'" aria-label="'+esc(e.name+' '+K[e.type])+' 탐색" transform="translate('+p.x+','+p.y+')"><rect class="node-box" x="-75" y="-36" width="150" height="72" rx="9"/><circle cx="-59" cy="-22" r="3" fill="'+(central?'#287461':colors[e.type])+'"/><text class="node-kind" x="-49" y="-18">'+K[e.type]+'</text><text class="node-name" text-anchor="middle" x="0" y="'+(lines.length>1?1:9)+'">'+lines.map((line,i)=>'<tspan x="0" dy="'+(i?18:0)+'">'+esc(line)+'</tspan>').join('')+'</text></g>';}).join('');
  el.innerHTML='<svg class="graph-svg" viewBox="0 0 '+w+' '+h+'" role="group" aria-label="'+esc(focus.name)+' 관계 지도"><title>'+esc(focus.name)+'와 직접 연결된 '+shown.length+'개 항목</title><defs><pattern id="graph-grid" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="#54768b" opacity=".28"/></pattern></defs><rect width="100%" height="100%" fill="url(#graph-grid)"/>'+edgeHtml+nodeHtml+'</svg>';
 }
 function sourceHtml(id){const s=S.get(id);return !s?'':'<a class="source-link" href="'+esc(safeUrl(s.url))+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗<span>'+esc(s.publisher)+' · '+esc(s.country)+' · '+esc(s.type)+' · '+(s.date?'발표/판본 '+esc(s.date):'발표일 미기재')+' · 검토 '+esc(s.reviewed)+'</span></a>';}
 function evidenceHtml(id){const items=research.evidenceFor(id);return '<section class="claim-evidence"><p class="section-title">주장별 확인 근거 · '+items.length+'</p>'+(items.length?items.map(item=>'<details><summary>'+esc(item.kind)+' · '+esc(S.get(item.source).publisher)+'</summary><p>'+esc(item.claim)+'</p><p class="evidence-note">확인 위치: '+esc(item.locator)+'<br>확인 한계: '+esc(item.limitation)+'</p>'+sourceHtml(item.source)+'</details>').join(''):'<p class="evidence-note">기존 출처는 아래에 연결돼 있지만 주장별 확인 위치는 아직 정리되지 않았습니다.</p>')+'</section>';}
 function detailHtml(e,full){const connections=neighbors(e.id);return '<div class="kind-label">'+K[e.type]+' <span>·</span> '+fieldOf(e.field).short+'</div>'+(full?'':'<h2>'+esc(e.name)+'</h2>')+'<p class="detail-subtitle">'+esc(e.subtitle)+'</p>'+pill(e)+'<p class="detail-summary">'+esc(e.summary)+'</p><div class="detail-actions"><button class="button secondary bookmark-button '+(saved.has(e.id)?'is-saved':'')+'" type="button" data-save="'+e.id+'" aria-pressed="'+saved.has(e.id)+'">'+(saved.has(e.id)?'★ 관심 목록에 저장됨':'☆ 관심 목록에 저장')+'</button>'+(full?'<button class="button secondary" type="button" data-focus="'+e.id+'">관계 지도 ↗</button>':'<button class="button secondary" type="button" data-open="'+e.id+'">상세 보기 ↗</button>')+'</div>'+(e.metrics.length?'<p class="section-title">확인된 구성·조건</p><dl>'+e.metrics.map(([k,v])=>'<div class="metric-row"><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>':'')+(e.question?'<p class="section-title">추적할 질문</p><p class="evidence-note">'+esc(e.question)+'</p>':'')+(e.notes?'<p class="evidence-note">'+esc(e.notes)+'</p>':'')+'<p class="section-title">연결된 항목 · '+connections.length+'</p><div class="relation-list">'+connections.map(n=>'<div class="relation-row"><button type="button" data-focus="'+n.entity.id+'">'+esc(n.entity.name)+' ↗</button><span>'+esc(n.link.label)+'</span></div>').join('')+'</div><p class="section-title">근거 자료</p>'+evidenceHtml(e.id)+sourceIds(e).map(sourceHtml).join('')+'<p class="field-tag">항목 검토 '+esc(e.reviewed)+'</p>';
 }
 function openDialog(id){const e=E.get(id);if(!e)return;returnFocus=document.activeElement;$('dialog-content').innerHTML='<div class="dialog-heading"><div><p class="overline">ENTITY PROFILE</p><h2>'+esc(e.name)+'</h2></div><button type="button" class="close-button" data-close="detail-dialog" aria-label="닫기">×</button></div><div class="dialog-body"><div class="detail-panel">'+detailHtml(e,true)+'</div></div>';if(!$('detail-dialog').open)$('detail-dialog').showModal();$('detail-dialog').scrollTop=0;}
 function openEdge(id){const l=D.links.find(x=>x.id===id);if(!l)return;const a=E.get(l.from),b=E.get(l.to);returnFocus=document.activeElement;$('dialog-content').innerHTML='<div class="dialog-heading"><div><p class="overline">RELATIONSHIP EVIDENCE</p><h2>'+esc(l.label)+'</h2></div><button type="button" class="close-button" data-close="detail-dialog" aria-label="닫기">×</button></div><div class="method-body"><p><strong>'+esc(a.name)+'</strong> ↔ <strong>'+esc(b.name)+'</strong></p><p>'+esc(l.scope)+'</p>'+(l.sources||[l.source]).map(sourceHtml).join('')+'<p class="evidence-note">'+esc(S.get(l.source).note)+'</p><button type="button" class="button secondary" data-focus="'+b.id+'">'+esc(b.name)+' 탐색 ↗</button></div>';if(!$('detail-dialog').open)$('detail-dialog').showModal();}
 function timelineEvents(){return D.events.filter(e=>{const n=E.get(e.entity);return inField(n,state.field)&&(state.type==='all'||n.type===state.type)&&(!state.query||matches(n,state.query)||normalize(e.title+' '+e.summary).includes(normalize(state.query)));});}
 function renderTimeline(){let list=timelineEvents();list.sort((a,b)=>b.date.localeCompare(a.date));if(!list.length){$('view-content').innerHTML=empty('표시할 변화 기록이 없습니다.','분야, 유형 또는 검색어를 변경해 주세요.');return;}let year='';$('view-content').innerHTML='<div class="timeline">'+list.map(e=>{const current=e.date.slice(0,4);const heading=current!==year?'<h2 class="year-heading">'+current+'</h2>':'';year=current;return heading+'<article class="timeline-row"><time class="event-date" datetime="'+e.date+'">'+(e.date.length===4?'연도만 확인':e.date.slice(5).replace('-','.'))+'</time><div><button class="event-title" type="button" data-open="'+e.entity+'">'+esc(e.title)+'</button><p>'+esc(e.summary)+'</p><div class="event-meta"><span class="status-pill '+(/설계|갱신/.test(e.kind)?'plan':'')+'">'+esc(e.kind)+'</span><span>'+esc(E.get(e.entity).name)+'</span><a href="'+esc(safeUrl(S.get(e.source).url))+'" target="_blank" rel="noopener noreferrer">'+esc(S.get(e.source).publisher)+' 원문 ↗</a></div></div></article>';}).join('')+'</div>';}
 function visibleSources(){return research.searchSources(state.query,{field:state.field,country:state.sourceCountry,type:state.sourceType});}
 function sourceFilter(id,label,key,value){return '<label>'+label+' <select id="'+id+'"><option value="all">전체</option>'+[...new Set(D.sources.map(s=>s[key]))].sort((a,b)=>a.localeCompare(b,'ko')).map(v=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';}
 function renderSources(){
  const list=visibleSources();
  const totalClaims=list.flatMap(s=>research.sourceEvidence(s.id)).length;
  const intro='<div class="evidence-toolbar">'+sourceFilter('source-country','발행기관 국가·지역','country',state.sourceCountry)+sourceFilter('source-type','자료 유형','type',state.sourceType)+'</div><p class="filter-note">'+list.length+'개 출처 · '+new Set(list.map(s=>s.originGroup)).size+'개 발행 계열 · '+totalClaims+'개 주장별 근거. 발행 계열 수는 독립 실험·검증 횟수가 아닙니다.</p>';
  $('view-content').innerHTML=intro+(list.length?'<div class="sources-grid">'+list.map(s=>'<article class="source-record"><div>'+esc(s.publisher)+'<small>'+esc(s.country)+' · '+esc(s.type)+'</small><small>발행 계열: '+esc(s.originGroup)+'</small></div><div><a href="'+esc(safeUrl(s.url))+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗</a><small>'+esc(s.note)+'</small>'+research.sourceEvidence(s.id).map(item=>'<details class="source-claims"><summary>'+esc(item.kind)+' · 확인 내용</summary><p>'+esc(item.claim)+'</p><small>위치: '+esc(item.locator)+'</small><div class="evidence-targets">'+item.entities.map(id=>'<button type="button" class="text-link" data-open="'+esc(id)+'">'+esc(E.get(id).name)+'</button>').join('')+'</div></details>').join('')+'</div><span class="source-date">'+(s.date?esc(s.date):'발표일 미기재')+'<small>검토 '+esc(s.reviewed)+'</small></span></article>').join('')+'</div>':empty('일치하는 근거 자료가 없습니다.','검색어, 국가·지역 또는 자료 유형을 변경해 주세요.'));
 }
 function setField(id){if(id!=='all'&&!fieldOf(id))return;state.field=id;state.focus=(fieldOf(id)||D.fields[0]).root;render();}
 function focusNode(id){const e=E.get(id);if(!e)return;if($('detail-dialog').open)$('detail-dialog').close();state.focus=id;state.view='map';state.query='';state.type='all';$('search').value='';if(!inField(e,state.field))state.field=e.field;render();$('view-content').scrollIntoView({block:'nearest'});}
 function reset(){state.sourceCountry='all';state.sourceType='all';state.query='';state.type='all';state.field='all';$('search').value='';state.focus='onboard-ai';render();}
 function exportRows(){let rows,filename='satellite-tech-atlas';if(state.view==='sources'){rows=[['자료','기관','유형','발표·갱신일','URL','검토일','국가·지역','발행 계열','확인 주장·위치·한계'],...visibleSources().map(s=>[s.title,s.publisher,s.type,s.date||'미기재',s.url,s.reviewed,s.country,s.originGroup,research.sourceEvidence(s.id).map(item=>item.claim+' / '+item.locator+' / '+item.limitation).join(' | ')])];}else if(state.view==='timeline'){rows=[['날짜','종류','기록','대상','설명','근거URL'],...timelineEvents().map(e=>[e.date,e.kind,e.title,E.get(e.entity).name,e.summary,S.get(e.source).url])];}else {const list=pageEntities();rows=[['항목','유형','분야','상태','설명','확인범위','근거URL','검토일','주장별 근거'],...list.map(e=>[e.name,K[e.type],fieldOf(e.field).name,e.status,e.summary,e.notes,sourceIds(e).map(id=>S.get(id).url).join(' | '),e.reviewed,research.evidenceFor(e.id).map(item=>item.claim+' / '+item.locator+' / '+item.limitation+' / '+S.get(item.source).url).join(' | ')])];}if(rows.length<2){toast('내보낼 항목이 없습니다.');return;}const csv='\ufeff'+rows.map(row=>row.map(value=>{let v=String(value??'');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename+'-'+state.view+'-'+D.reviewed+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast((rows.length-1)+'개 기록을 내보냈습니다.');}
 $('method-body').innerHTML='<p>이 지도는 <strong>'+D.reviewed+'</strong>에 검토한 공개자료를 선별해 구성한 데이터셋입니다. 개별 항목과 출처의 검토일은 상세 화면에서 확인할 수 있습니다. 전체 산업을 망라하지 않으며 자동 실시간 수집은 연결되어 있지 않습니다.</p><h3>성과의 범위를 구분합니다</h3><ul><li><strong>설계·개발 목표:</strong> 구현하려는 기능과 목표값. 달성 여부는 별도 확인합니다.</li><li><strong>탑재 확인:</strong> 위성에 사용된 구성. 모든 기능의 성공이나 다른 궤도의 적합성을 뜻하지 않습니다.</li><li><strong>기관 성과발표:</strong> NASA·ESA 등 임무 주관기관이 발표한 결과.</li><li><strong>개발사 실증발표:</strong> 제조사가 공개한 기록. 독립된 시험 결과와 구분합니다.</li><li><strong>제품화·기술조사 수록:</strong> 제품 또는 조사표의 존재. 양산 수량·수주·매출은 별도 근거가 필요합니다.</li></ul><h3>연결선의 의미</h3><p>개발, 탑재, 컨소시엄 참여, 관련 기술을 각각 표시합니다. 기술 분류나 같은 사업 참여만으로 직접적인 구매·공급계약을 추정하지 않습니다. 각 연결선을 누르면 관계의 확인 범위와 원문을 볼 수 있습니다.</p><h3>날짜와 빈 정보</h3><p>발사·임무 종료 등의 사건 날짜와 발표·갱신일을 구분합니다. 원문이 연도나 월까지만 제시하면 해당 정밀도를 보존합니다. 자료가 없으면 미확인으로 남기며 임의의 TRL·점수·성장률을 생성하지 않습니다.</p><h3>조사 범위</h3><p>'+D.fields.length+'개 분야 · '+D.entities.filter(e=>e.type==='organization').length+'개 기업·기관 · '+D.entities.filter(e=>e.type==='product').length+'개 제품·장비 · '+D.entities.filter(e=>e.type==='mission').length+'개 실증임무. 국내 사례로 TelePIX와 KARI 아리랑 3A호를 포함합니다. 국가별 전수조사는 아니며 기관·제조사·연구팀 자료를 함께 비교합니다.</p><h3>근거 취합 범위</h3><p>원문 '+D.sources.length+'개와 주장별 근거 '+D.evidence.length+'개를 연결했습니다. 근거 자료 화면에서 발행기관 국가·지역과 자료 유형으로 좁힐 수 있습니다. 같은 사업·연구팀의 자료는 독립 검증으로 집계하지 않습니다. 기존 출처 중 주장별 확인 위치가 정리되지 않은 항목은 별도 안내합니다.</p><h3>수록 분야</h3><div class="roadmap">'+D.fields.map(f=>'<span>'+esc(f.name)+'</span>').join('')+'</div><h3>관심 목록과 내보내기</h3><p>관심 목록은 현재 브라우저에 저장됩니다. 기기 사이에서 동기화되지 않습니다. 현재 탐색 결과나 관심 목록을 출처가 포함된 CSV로 내려받을 수 있습니다.</p>';
 document.addEventListener('click',event=>{const el=event.target.closest('[data-view],[data-field],[data-focus],[data-open],[data-save],[data-close],[data-edge],[data-root],[data-reset]');if(!el)return;if(el.dataset.view){state.view=el.dataset.view;render();}else if(el.dataset.field)setField(el.dataset.field);else if(el.dataset.save)saveItem(el.dataset.save);else if(el.dataset.focus)focusNode(el.dataset.focus);else if(el.dataset.open)openDialog(el.dataset.open);else if(el.dataset.close)$(el.dataset.close).close();else if(el.dataset.edge)openEdge(el.dataset.edge);else if(el.hasAttribute('data-root'))focusNode((fieldOf(state.field)||D.fields[0]).root);else if(el.hasAttribute('data-reset'))reset();});
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 document.addEventListener('change',e=>{if(e.target.id==='mobile-field')setField(e.target.value);if(e.target.id==='source-country'){state.sourceCountry=e.target.value;renderSources();}if(e.target.id==='source-type'){state.sourceType=e.target.value;renderSources();}});
 $('search').addEventListener('input',e=>{state.query=e.target.value;renderContext();renderContent();});
 $('type-filter').addEventListener('change',e=>{state.type=e.target.value;renderContent();});
 $('clear-filters').addEventListener('click',reset);
 $('method-button').addEventListener('click',()=>{$('method-dialog').showModal();$('method-dialog').scrollTop=0;});
 $('export-button').addEventListener('click',exportRows);
 for(const id of ['detail-dialog','method-dialog']){$(id).addEventListener('click',e=>{if(e.target!==$(id))return;const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(id).close();});}
 $('detail-dialog').addEventListener('close',()=>{if(returnFocus&&document.contains(returnFocus))returnFocus.focus();});
 window.addEventListener('hashchange',()=>{readHash();render();});
 window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.view==='map'&&!state.query&&state.type==='all')renderMap();},180);});
 $('dataset-date').textContent='자료 검토 '+D.reviewed;$('review-date').textContent=D.reviewed;
 readHash();render();
 // Read-only integration surface, also used by data integrity checks.
 window.SatelliteAtlas={search:(query='',field='all')=>D.entities.filter(e=>inField(e,field)&&matches(e,query)),getEntity:id=>E.get(id),getConnections:id=>neighbors(id),getEvidence:research.evidenceFor,searchSources:research.searchSources,getCoverage:research.coverage,getSources:id=>E.has(id)?sourceIds(E.get(id)).map(s=>S.get(s)):[],focus:focusNode,getState:()=>({...state}),getSaved:()=>[...saved]};
})();
